    int MAX_PAGE_SIZE = 100;

    MemberLoanPage getActiveLoans(GetMemberLoansQuery query);

    record GetMemberLoansQuery(UUID memberId, int page, int size) {

        public GetMemberLoansQuery {
            if (memberId == null) {
