package com.example.lending;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import org.junit.jupiter.api.Test;
import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.boot.test.autoconfigure.web.servlet.AutoConfigureMockMvc;
import org.springframework.boot.test.context.SpringBootTest;
import org.springframework.http.MediaType;
import org.springframework.test.web.servlet.MockMvc;

import java.util.UUID;

import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.get;
import static org.springframework.test.web.servlet.request.MockMvcRequestBuilders.post;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.jsonPath;
import static org.springframework.test.web.servlet.result.MockMvcResultMatchers.status;

@SpringBootTest
@AutoConfigureMockMvc
class LendingIntegrationTest {

    @Autowired
    MockMvc mockMvc;

    @Autowired
    ObjectMapper objectMapper;

    @Test
    void loaning_a_book_already_on_loan_returns_409() throws Exception {
        String registered = mockMvc.perform(post("/books")
                        .contentType(MediaType.APPLICATION_JSON)
                        .content("{\"title\":\"Clean Architecture\"}"))
                .andExpect(status().isCreated())
                .andExpect(jsonPath("$.status").value("AVAILABLE"))

content.content:
    String onLoan = registerBook();
    loan(onLoan, memberId);
    mockMvc.perform(post("/books/" + onLoan + "/discard"))
            .andExpect(status().isConflict())
            .andExpect(jsonPath("$.error").value("BOOK_ON_LOAN"));

    mockMvc.perform(post("/books/" + UUID.randomUUID() + "/discard")).andExpect(status().isNotFound());
}

@Test
void returning_unknown_loan_returns_404() throws Exception {
    mockMvc.perform(post("/loans/" + UUID.randomUUID() + "/return")).andExpect(status().isNotFound());
}

@Test
void late_fee_is_100_won_per_day_after_the_due_date() throws Exception {
    Object[][] cases = {{"2026-01-15", 0, 0}, {"2026-01-16", 1, 100}, {"2026-01-20", 5, 500}};
    for (Object[] c : cases) {
        String loanId = loanAt(registerBook(), registerMember(), "2026-01-01");
        mockMvc.perform(post("/loans/" + loanId + "/return").contentType(MediaType.APPLICATION_JSON)
                        .content("{\"returnedAt\":\"" + c[0] + "\"}"))
                .andExpect(status().isOk())
                .andExpect(jsonPath("$.returnedAt").value(c[0]))
                .andExpect(jsonPath("$.overdueDays").value(c[1]))
                .andExpect(jsonPath("$.lateFee").value(c[2]));
    }
}

@Test
void return_before_loan_date_returns_400() throws Exception {
    String loanId = loanAt(registerBook(), registerMember(), "2026-01-01");
    mockMvc.perform(post("/loans/" + loanId + "/return").contentType(MediaType.APPLICATION_JSON)
                    .content("{\"returnedAt\":\"2025-12-31\"}"))
            .andExpect(status().isBadRequest());
}

@Test
void return_without_date_has_no_late_fee() throws Exception {
    String loanId = loan(registerBook(), registerMember());
    mockMvc.perform(post("/loans/" + loanId + "/return").contentType(MediaType.APPLICATION_JSON).content("{}"))
            .andExpect(status().isOk())
            .andExpect(jsonPath("$.overdueDays").value(0))
            .andExpect(jsonPath("$.lateFee").value(0));
}

@Test
void member_loans_are_paged_and_exclude_returned() throws Exception {
    String memberId = registerMember();
    String first = loanAt(registerBook(), memberId, "2026-02-01");
    loanAt(registerBook(), memberId, "2026-02-02");
    loanAt(registerBook(), memberId, "2026-02-03");
    loanAt(registerBook(), memberId, "2026-02-04");
    mockMvc.perform(post("/loans/" + first + "/return").contentType(MediaType.APPLICATION_JSON).content("{}"))
            .andExpect(status().isOk());

    mockMvc.perform(get("/members/" + memberId + "/loans?page=0&size=2"))
            .andExpect(status().isOk())
            .andExpect(jsonPath("$.items.length()").value(2))
            .andExpect(jsonPath("$.items[0].loanedAt").value("2026-02-02"))
            .andExpect(jsonPath("$.items[0].title").value("책"))
            .andExpect(jsonPath("$.page").value(0))
            .andExpect(jsonPath("$.size").value(2))
            .andExpect(jsonPath("$.totalCount").value(3));
    mockMvc.perform(get("/members/" + memberId + "/loans?page=1&size=2"))
            .andExpect(jsonPath("$.items.length()").value(1))
            .andExpect(jsonPath("$.totalCount").value(3));
    mockMvc.perform(get("/members/" + memberId + "/loans?page=5&size=2"))
            .andExpect(jsonPath("$.items.length()").value(0))
            .andExpect(jsonPath("$.totalCount").value(3));
}

@Test
void member_loans_validates_input_and_member() throws Exception {
    mockMvc.perform(get("/members/" + registerMember() + "/loans?page=-1&size=2")).andExpect(status().isBadRequest());
    mockMvc.perform(get("/members/" + registerMember() + "/loans?size=0")).andExpect(status().isBadRequest());
    mockMvc.perform(get("/members/" + UUID.randomUUID() + "/loans")).andExpect(status().isNotFound());
}

private String loanAt(String bookId, String memberId, String loanedAt) throws Exception {
    String body = mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                    .content("{\"bookId\":\"" + bookId + "\",\"memberId\":\"" + memberId
                            + "\",\"loanedAt\":\"" + loanedAt + "\"}"))
            .andExpect(status().isCreated()).andReturn().getResponse().getContentAsString();
    return objectMapper.readTree(body).get("loanId").asText();
}

private String loan(String bookId, String memberId) throws Exception {
    String body = mockMvc.perform(post("/loans").contentType(MediaType.APPLICATION_JSON)
                    .content(objectMapper.writeValueAsString(new LoanBody(bookId, memberId))))
            .andExpect(status().isCreated()).andReturn().getResponse().getContentAsString();
    return objectMapper.readTree(body).get("loanId").asText();
}

private String registerMember() throws Exception {
    String body = mockMvc.perform(post("/members").contentType(MediaType.APPLICATION_JSON).content("{\"name\":\"대출자\"}"))
            .andExpect(status().isCreated()).andReturn().getResponse().getContentAsString();
    return objectMapper.readTree(body).get("memberId").asText();
}

private String registerBook() throws Exception {
    String body = mockMvc.perform(post("/books").contentType(MediaType.APPLICATION_JSON).content("{\"title\":\"책\"}"))
            .andExpect(status().isCreated()).andReturn().getResponse().getContentAsString();
    return objectMapper.readTree(body).get("id").asText();
}

