package com.example.lending.application.service;

import com.example.lending.application.port.in.GetMemberLoanHistoryUseCase;
import com.example.lending.application.port.out.LoadLoanHistoryPort;
import com.example.lending.application.port.out.LoadMemberPort;
import com.example.lending.domain.Loan;
import com.example.lending.domain.MemberNotFoundException;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.Transactional;

import java.util.List;
import java.util.UUID;

@Service
@Transactional(readOnly = true)
public class GetMemberLoanHistoryService implements GetMemberLoanHistoryUseCase {

    private final LoadMemberPort loadMemberPort;
    private final LoadLoanHistoryPort loadLoanHistoryPort;

    public GetMemberLoanHistoryService(LoadMemberPort loadMemberPort, LoadLoanHistoryPort loadLoanHistoryPort) {
        this.loadMemberPort = loadMemberPort;
        this.loadLoanHistoryPort = loadLoanHistoryPort;
    }

    @Override
    public List<LoanHistoryItem> getLoanHistory(UUID memberId) {
        loadMemberPort.loadMember(memberId).orElseThrow(() -> new MemberNotFoundException(memberId));
        return loadLoanHistoryPort.loadLoanHistory(memberId).stream()
                .map(e -> {
                    Loan loan = e.loan();
                    Integer lateFee = loan.isReturned() ? loan.lateFee() : null;
                    return new LoanHistoryItem(loan.getId(), e.title(), loan.getLoanedAt(), loan.getReturnedAt(), lateFee);
                })
                .toList();
    }
}
